(window.webpackJsonp=window.webpackJsonp||[]).push([[3],{333:function(e,t,n){"use strict";n.r(t),t.default={meta:{siteName:"NTCH Arts and Cultural Concourse",docDesc:"NTCH Art and Cultural Concourse is designed as an underground connection for art, life, culture, and sustainability.",docThumb:"",currentUrl:"",keyWords:"Sustainable Theater"},navigation:[{title:"Vision",link:"#plan"},{title:"What’s New",link:"#news"},{title:"Goals and Functions",link:"#intro"},{title:"Milestones",link:"#point"}],esg_link:"https://npac-ntch.org/zh",footer_text:"Copyright ® National Performing Arts Center - National Theater & Concert Hall",video_title:"“ A Sustainable Theater,<br>A World for Us All  ”",top_title:"Connect the Art for <span>All</span>",top_desc:"<p>NTCH Art and Cultural Concourse is designed as an underground connection for art, life, culture, and sustainability.</p><p>Upon completion in 2027, the concourse will connect MRT C.K.S. Memorial Hall Station Exit 5 and NTCH underground spaces. This convenient pedestrian and accessible route also provides creative and promotion environments and opportunities. Everyone is welcomed to NTCH for all.</p>",wave_en_title:"VISION",wave:[{title:"connect to people",en_title:"Underground connection ensures convenient and equal access to arts",text:"The concourse covers three stories underground. From MRT C.K.S. Memorial Hall Exit 5, the concourse on B2 level leads to NTCH parking lots at B1 level. Two accessible elevators and escalators will be installed along the way for equal access. Users with disabilities, wheelchairs, and strollers will be able to arrive at NTCH directly.",img1:["img/public/wave-1.jpg"],img2:["img/public/wave-2.png"]},{title:"CONNECT TO ART",en_title:"More spaces for publicity and rehearsals",text:"The project not only builds a convenient path, but also offers spaces for publicity and leisure purposes. It brings art and culture closer to daily life for everyone, without any impacts on existing performing spaces. Besides public areas for publicity, the new rehearsal room will be the same size as the National Theater stage. Before official shows, performers will have sufficient spaces for practical and technical tests. This is a substantial help to performing arts industries. The concourse supports creators, and provides better public access to art and culture.",img1:["img/public/wave-3.png"],img2:["img/public/wave-4.jpg"]},{title:"connect to<br>the environment",en_title:"A sustainable theater that benefits all",text:"In the preparatory period, NTCH has reviewed available infrastructure, improved walkway and roadway systems, and enhanced greenery and leisure areas at the ground level. These efforts aim to create an art oasis friendly to all. Upon completion, pedestrian experiences will be much better and safer. It will encourage more visitors to come by metro as a sustainable option with fewer carbon footprints.",img1:["img/public/wave-5.jpg"],img2:["img/public/wave-6.jpg"]}],news_title:"What’s New",more_text:"more info",important_title:"Major Announcements",important:[{title:"Big Forest Closure since May 21st (Monday) for Construction",year:"2025",mouth:"04",day:"25",link:"https://npac-ntch.org/tender-and-announcement/announcement/12106-Big%20Forest%20Closure%20since%20May%2021st%20(Monday)%20for%20Construction?lang=en-US"},{title:"Vehicle Route Change since May 19th (Monday) at National Theater",year:"2025",mouth:"04",day:"25",link:"https://npac-ntch.org/tender-and-announcement/announcement/12107-Vehicle%20Route%20Change%20since%20May%2019th%20(Monday)%20at%20National%20Theater?lang=en-US"},{title:"Alternative Routes Between NTCH and MRT Exit 5 During Construction Time",year:"2024",mouth:"Oct",day:"25",link:"https://npac-ntch.org/tender-and-announcement/announcement/11382-Alternative%20Routes%20Between%20NTCH%20and%20MRT%20Exit%205%20During%20Construction%20Time?lang=en-US"},{title:"Entrance Change for NTCH Basement Parking Garage by Aiguo E Rd:",year:"2024",mouth:"Jul",day:"09",link:"https://npac-ntch.org/tender-and-announcement/announcement/10743-Entrance%20Change%20for%20NTCH%20Basement%20Parking%20Garage%20by%20Aiguo%20E%20Rd?lang=en-US"}],expose_title:"新聞露出",expose:[],plan_title:"Goals and Functions",plan_desc:"The project will construct a new Art and Cultural Concourse, and improve on the following items:",plan_list:["・ Sidewalks in underground parking lots","・ Open space integration in the Little Forest","・ Spatial improvement in the Big Forest","・ Sidewalks and curbs"],plan_data:[{title:"Concourse Construction Area & Little Forest",img:["img/public/intro-1-en-png.png"]},{title:"NTCH Underground Parking Lot",img:["img/public/intro-2-en-png.png"]},{title:"Big Forest",img:["img/public/intro-3-en-png.png"]},{title:"The project will enhance and redesign underground spaces and ground-level greenery. The parking lot entrance on Aiguo East Road will be combined with the Little Forest into an open and safe space for pedestrians.",before:{title:"—Before",desc:"Pedestrian routes from MRT Exit 5 can be confusing, and prone to friction with vehicles on the way to National Theater and the square."},after:{title:"—After",desc:"Pedestrian and vehicle routes are reorganized on ground and underground levels, underground spaces are optimized, and pedestrian and Little Forest areas on ground level are extended."},img:["img/public/intro-4-en-png.png"]},{title:"Structure of the Art and Cultural Concourse",img:["img/public/intro-5-en-png.png"]}],point_title:"Milestones",swiper_data:[{year:2027,content:"Continuation of structural & MEP works.<br>Commencement of finishing works, Small Forest open space Integration,<br>underground parking pedestrian system upgrades,<br>and driveway pedestrian access & bollard improvements.<br>Full project completion by year-end."},{year:2026,content:"King post works completed in April.<br>Excavation works started in May.<br>Structural & MEP works scheduled."},{year:2025,content:"Big Forest space improvement works started in May.<br>Building Permit Amendment Application approved in November.<br>Temporary work and partial foundation works completed in December."},{year:2024,content:"Executive Yuan approved the second<br>amended project.<br>The construction commenced"},{year:2023,content:"Tree relocation bid closed, <br>main construction bid began",title:"External communication",additional:"Multiple workshops were held for members, the public, accessibility advocates, performing arts groups, community colleges, and residents to inform and discuss construction plans."},{year:2022,content:"Detailed design completed, heritage and <br>cultural landscape evaluation completed"},{year:2021,content:"Executive Yuan approved the amended<br>project and selected the designer <br>(Shu Chang & associates)"},{year:2020,content:"Vendor was selected for project <br>management and supervision"},{year:2019,content:"Executive Yuan approved the <br>infrastructure project"}]}}}]);